export function applyDiscount(lineItems: {
    quantity: number;
    unitCents: number;
}[], discountPercent: number) {
    const subtotalCents = lineItems.reduce((s, x) => s + x.quantity * x.unitCents, 0);
    const discountedCents = Math.round(subtotalCents * (100 - discountPercent) / 100);
    return { subtotalCents, discountCents: subtotalCents - discountedCents, totalCents: discountedCents };
}
